.Lanon.0baec5b44c5538d1487548c085149cb7.4676:
	.ascii	"additional-properties-schema-widened"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4676, 36

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4677,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4677,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4677:
	.ascii	"A schema-valued additionalProperties assertion constrains arbitrary object members, while SHACL Core closure can only reject unlisted direct predicates. Named properties remain constrained and the arbitrary-value schema is widened."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4677, 231

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4678,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4678,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4678:
	.ascii	"annotation-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4678, 18

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4679,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4679,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4679:
	.ascii	"A schema title, description, comment, example, default, deprecation marker, or native documentation annotation has no exact validation meaning in the imported SHACL shape and is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4679, 186

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4680,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4680,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4680:
	.ascii	"array-contains-validation-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4680, 33

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4681,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4681,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4681:
	.ascii	"Schema contains/minContains/maxContains assertions quantify matching array members; the imported SHACL property retains item and total-cardinality constraints but cannot express that independent match count exactly."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4681, 215

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4682,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4682,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4682:
	.ascii	"boolean-schema-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4682, 22

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4683,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4683,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4683:
	.ascii	"A standalone true or false schema has no class-targeted SHACL shape identity. The definition is omitted rather than inventing a caller vocabulary term."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4683, 151

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4684,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4684,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4684:
	.ascii	"conditional-validation-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4684, 30

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4685,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4685,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4685:
	.ascii	"Schema if/then/else validation chooses constraints from runtime object content. SHACL Core has no equivalent conditional constraint, so independently representable constraints remain and the conditional relationship is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4685, 227

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4686,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4686,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4686:
	.ascii	"content-validation-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4686, 26

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4687,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4687,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4687:
	.ascii	"String contentEncoding/contentMediaType/contentSchema assertions describe or validate an embedded representation. SHACL Core constrains the RDF literal itself and cannot reproduce that nested content contract."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4687, 209

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4688,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4688,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4688:
	.ascii	"dependency-validation-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4688, 29

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4689,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4689,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4689:
	.ascii	"dependentRequired/dependentSchemas or an equivalent native cross-field dependency has no exact SHACL Core property-shape expression. Individual properties remain while the dependency is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4689, 194

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4690,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4690,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4690:
	.ascii	"enum-metadata-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4690, 21

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4691,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4691,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4691:
	.ascii	"A schema enum member's generated symbol, title, description, or other parallel metadata is not part of SHACL membership semantics and is omitted while the finite values remain."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4691, 176

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4692,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4692,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4692:
	.ascii	"format-validation-widened"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4692, 25

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4693,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4693,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4693:
	.ascii	"A string format without one exact caller-identifiable RDF datatype is imported as its scalar carrier. PurRDF does not mint or guess a datatype IRI, so format validation is widened and recorded."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4693, 193

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4694,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4694,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4694:
	.ascii	"multiple-of-validation-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4694, 30

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4695,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4695,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4695:
	.ascii	"A numeric multipleOf assertion has no SHACL Core numeric facet. Datatype and range bounds remain while divisibility validation is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4695, 138

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4696,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4696,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4696:
	.ascii	"non-object-definition-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4696, 29

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4697,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4697,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4697:
	.ascii	"A top-level schema definition describes a scalar, array, finite value set, or alias rather than a class-shaped object. Without a caller-supplied class/property use site it cannot become a top-level SHACL node shape and is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4697, 230

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4698,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4698,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4698:
	.ascii	"numeric-lexical-form-normalized"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4698, 31

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4699,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4699,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4699:
	.ascii	"A JSON/native numeric value carries numeric value but not the original RDF literal lexical form or derived XSD datatype. The importer uses the canonical configured numeric carrier, so that lexical distinction is normalized."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4699, 223

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4700,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4700,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4700:
	.ascii	"object-key-validation-dropped"
