	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4701,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4701:
	.ascii	"patternProperties/propertyNames or an equivalent native dynamic-key rule constrains JSON member names. Direct SHACL predicate paths retain named properties, but the dynamic key-space rule is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4701, 199

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4702,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4702,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4702:
	.ascii	"property-count-validation-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4702, 33

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4703,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4703,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4703:
	.ascii	"minProperties/maxProperties counts JSON object members independently of named predicates. SHACL property shapes retain named requiredness but cannot bound the total predicate count with a Core constraint."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4703, 204

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4704,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4704,"a",@progbits
