	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4705,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4705,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4705:
	.ascii	"A schema logical applicator cannot be lowered to an equivalent finite SHACL and/or/xone/not shape at its position. Independently representable constraints remain and the applicator is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4705, 192

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4706,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4706,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4706:
