	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4707,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4707:
	.ascii	"A schema document identifier, anchor, dialect declaration, generated package identity, or native module identity is not a SHACL vocabulary term. Caller-owned class and property IRIs remain; the carrier identity is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4707, 222

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4708,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4708,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4708:
