	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4709,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4709:
	.ascii	"Position-specific prefixItems/additionalItems or an equivalent tuple type has no direct RDF multi-value ordering contract on one predicate. Common item/cardinality constraints remain and positional validation is widened."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4709, 220

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4710,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4710,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4710:
	.ascii	"unevaluated-validation-dropped"
