	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4711,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4711:
	.ascii	"unevaluatedProperties/unevaluatedItems depends on schema-applicator evaluation state that SHACL Core does not expose. Local closure, named properties, and item constraints remain while the evaluation-state assertion is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4711, 227

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4712,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4712,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4712:
