	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4713,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4713:
	.ascii	"uniqueItems constrains duplicate JSON array members. RDF predicate values are a set in the data model, so the serialized-array assertion has no distinct imported SHACL constraint and is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4713, 194

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4714,@object
