	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4786,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4786,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4786:
	.ascii	"A shape targeted only via SHACL-AF sh:target/sh:SPARQLTarget (an arbitrary SPARQL SELECT, not a class extension) has no closed-world JSON Schema equivalent; the shape is excluded from the compiled $defs."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4786, 203

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4787,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4787,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4787:
	.ascii	"sh:disjoint"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4787, 11

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4788,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4788,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4788:
	.ascii	"A SHACL sh:disjoint constraint keeps the values apart from the nodes a property path (an IRI or any other SHACL 1.2 path) reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4788, 287

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4789,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4789,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4789:
	.ascii	"sh:equals"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4789, 9

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4790,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4790,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4790:
	.ascii	"A SHACL sh:equals constraint requires the values to be exactly the nodes a property path (an IRI or any other SHACL 1.2 path) reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4790, 291

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4791,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4791,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4791:
	.ascii	"sh:expression"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4791, 13

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4792,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4792,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4792:
	.ascii	"A SHACL-AF sh:expression node-expression constraint has no JSON Schema equivalent and is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4792, 97

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4793,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4793,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4793:
	.ascii	"sh:lessThan"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4793, 11

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4794,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4794,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4794:
	.ascii	"A SHACL sh:lessThan constraint orders the values below every node a property path (an IRI or any other SHACL 1.2 path) reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4794, 284

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4795,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4795,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4795:
	.ascii	"sh:lessThanOrEquals"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4795, 19

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4796,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4796,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4796:
	.ascii	"A SHACL sh:lessThanOrEquals constraint orders the values at or below every node a property path (an IRI or any other SHACL 1.2 path) reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4796, 298

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4797,@object
	.section	.rodata.cst16,"aM",@progbits,16
.Lanon.0baec5b44c5538d1487548c085149cb7.4797:
	.ascii	"sh:maxListLength"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4797, 16

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4798,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4798,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4798:
	.ascii	"A SHACL 1.2 sh:maxListLength constraint bounds the member count of a list value node (as maxItems) or focus node (as maxItems of its rdf:rest, less its own member); the instance projection carries a list JSON-LD 1.1 converts (Processing Algorithms and API 8.4.2) as its @list array, which the schema judges exactly; a list it keeps as linked @graph nodes (a cell with another property, referenced twice, or an IRI) is a node reference whose members hang off other @graph nodes, and a JSON Schema keyword judges only the instance location it applies to and those beneath it ($ref resolves schemas, never instance values), so for such a value the constraint is not checked."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4798, 671

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4799,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4799,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4799:
	.ascii	"sh:memberShape"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4799, 14

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4800,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4800,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4800:
	.ascii	"A SHACL 1.2 sh:memberShape constraint judges every member of a list value node or focus node against a shape (as items); the instance projection carries a list JSON-LD 1.1 converts (Processing Algorithms and API 8.4.2) as its @list array, which the schema judges exactly; a list it keeps as linked @graph nodes (a cell with another property, referenced twice, or an IRI) is a node reference whose members hang off other @graph nodes, and a JSON Schema keyword judges only the instance location it applies to and those beneath it ($ref resolves schemas, never instance values), so for such a value the constraint is not checked."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4800, 627

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4801,@object
	.section	.rodata.cst16,"aM",@progbits,16
.Lanon.0baec5b44c5538d1487548c085149cb7.4801:
	.ascii	"sh:minListLength"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4801, 16

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4802,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4802,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4802:
	.ascii	"A SHACL 1.2 sh:minListLength constraint bounds the member count of a list value node (as minItems) or focus node (as minItems of its rdf:rest, less its own member); the instance projection carries a list JSON-LD 1.1 converts (Processing Algorithms and API 8.4.2) as its @list array, which the schema judges exactly; a list it keeps as linked @graph nodes (a cell with another property, referenced twice, or an IRI) is a node reference whose members hang off other @graph nodes, and a JSON Schema keyword judges only the instance location it applies to and those beneath it ($ref resolves schemas, never instance values), so for such a value the constraint is not checked."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4802, 671

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4803,@object
	.section	.rodata.cst8,"aM",@progbits,8
.Lanon.0baec5b44c5538d1487548c085149cb7.4803:
	.ascii	"sh:class"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4803, 8

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4804,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4804,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4804:
	.ascii	"A sh:class constraint on a node shape (one class or a SHACL list of them) judges the focus node's own class membership through the data graph's rdfs:subClassOf* triples, which live on other @graph nodes; a JSON Schema keyword judges only the instance location it applies to and those beneath it, so none reaches them, and the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4804, 348

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4805,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4805,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4805:
	.ascii	"sh:closed sh:ByTypes"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4805, 20

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4806,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4806,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4806:
	.ascii	"A SHACL 1.2 sh:closed sh:ByTypes constraint permits the properties each value node's own rdf:type values collect through the shapes graph; an object schema states one fixed key set for every instance, so the object is left open and the constraint is dropped (on a property shape, whose value nodes are node references, likewise)."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4806, 329

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4807,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4807,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4807:
	.ascii	"sh:not"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4807, 6

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4808,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4808,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4808:
	.ascii	"A sh:not negation whose inner shape is not losslessly expressible as a JSON Schema negation (or that appears at property/value position, where negating a base value schema would be vacuous) is dropped rather than emitted unsoundly."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4808, 231

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4809,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4809,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4809:
	.ascii	"sh:nodeByExpression"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4809, 19

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4810,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4810,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4810:
	.ascii	"A SHACL 1.2 sh:nodeByExpression constraint computes its node shape from a node expression evaluated against the data graph; a closed-world JSON Schema has no way to express a shape that is not known until validation time, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4810, 251

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4811,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4811,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4811:
	.ascii	"sh:rootClass"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4811, 12

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4812,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4812,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4812:
	.ascii	"A SHACL 1.2 sh:rootClass constraint bounds class-valued value nodes (or the focus node) by the data graph's rdfs:subClassOf hierarchy; a closed-world JSON Schema cannot consult that hierarchy, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4812, 222

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4813,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4813,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4813:
	.ascii	"sh:someValue"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4813, 12

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4814,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4814,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4814:
	.ascii	"A SHACL 1.2 sh:someValue constraint on a property shape requires at least one of the property's values to conform to a shape; the emitted value schema constrains each value alone, so the constraint is dropped (on a node shape it is projected as sh:node is)."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4814, 257

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4815,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4815,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4815:
	.ascii	"sh:sparql"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4815, 9

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4816,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4816,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4816:
	.ascii	"A SHACL-SPARQL constraint (sh:sparql) has no closed-world JSON Schema equivalent and is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4816, 96

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4817,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4817,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4817:
	.ascii	"sh:subsetOf"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4817, 11

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4818,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4818,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4818:
	.ascii	"A SHACL 1.2 sh:subsetOf constraint requires every value to be among the nodes a property path reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4818, 259

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4819,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4819,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4819:
	.ascii	"sh:targetNode"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4819, 13

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4820,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4820,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4820:
	.ascii	"A shape targeted only via sh:targetNode selects specific focus nodes (a constant, or the output nodes of a node expression), not a class extension; it has no closed-world JSON Schema $def and its constraints are not enforced by the emitted schema."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4820, 247

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4821,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4821,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4821:
	.ascii	"sh:targetObjectsOf"
