.Lanon.0baec5b44c5538d1487548c085149cb7.4843:
	.ascii	"sh:qualifiedValueShape"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4843, 22

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4844,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4844,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4844:
	.ascii	"A sh:qualifiedValueShape constraint counts the value nodes that conform to a shape, which the value schema cannot judge from a node reference; on a node shape, where it is not well-formed, it judges the focus node itself, which an object schema describing the node's properties does not state, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4844, 323

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4845,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4845,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4845:
	.ascii	"sh:closed"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4845, 9

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4846,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4846,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4846:
	.ascii	"A sh:closed true constraint on a property shape limits the properties of each value node, which its node reference does not carry, so the constraint is dropped (on a node shape it is projected as additionalProperties false)."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4846, 224

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4847,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4847,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4847:
	.ascii	"sh:uniqueLang"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4847, 13

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4848,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4848,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4848:
	.ascii	"A sh:uniqueLang true constraint forbids two values sharing a language tag, which a schema constraining each value alone cannot state; on a node shape, where it is not well-formed, it judges the focus node itself, which an object schema describing the node's properties does not state, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4848, 314

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4849,@object
