.Lanon.0baec5b44c5538d1487548c085149cb7.4849:
	.ascii	"sh:ConstraintComponent"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4849, 22

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4850,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4850,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4850:
	.ascii	"A custom SPARQL-based constraint component (named in the note) validates through a SPARQL query, which has no closed-world JSON Schema equivalent, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4850, 176

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4851,@object
