	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4851, 11

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4852,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4852,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4852:
	.ascii	"A sh:minCount constraint on a node shape or a member shape, where it is not well-formed, judges the focus node itself rather than a property's values, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4852, 180

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4853,@object
