	.ascii	"sh:property"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4867, 11

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4868,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4868,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4868:
	.ascii	"A property shape nested under a property shape or a member shape judges each value node's (or member's) own properties, which live on that node's own @graph node; a JSON Schema keyword judges only the instance location it applies to and those beneath it, so none reaches them, and the nested shape is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4868, 309

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4869,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4869,"a",@progbits
