	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4869, 15

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4870,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4870,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4870:
	.ascii	"A SHACL 1.2 sh:reifierShape constraint judges the reifiers of each value's triple, which the projected value does not carry, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4870, 154

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4871,@object
