	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4871, 22

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4872,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4872,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4872:
	.ascii	"A SHACL 1.2 sh:reificationRequired true constraint requires each value's triple to be reified, which the projected value does not state, so the constraint is dropped."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4872, 166

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4873,@object
