	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4881,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4881:
	.ascii	"LinkML 1.11 has no per-class equivalent for JSON Schema's additionalProperties policy or schema. Named attributes retain their constraints, but acceptance of unlisted object keys is widened and recorded on the object schema."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4881, 224

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4882,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4882,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4882:
	.ascii	"A JSON Schema contains is stated as a LinkML has_member, which requires one matching member; LinkML 1.11 has no expression for a minContains above 1 or a maxContains, so those match-count bounds are omitted, as is a contains on a schema the projection renders as no slot expression."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4882, 282

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4883,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4883,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4883:
	.ascii	"JSON Schema if/then/else conditional validation has no LinkML 1.11 expression. Independently representable carrier constraints remain, while the conditional relationship is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4883, 181

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4884,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4884,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4884:
	.ascii	"JSON Schema dependentRequired/dependentSchemas validation has no LinkML 1.11 expression. Attribute constraints remain, while cross-property dependencies are omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4884, 165

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4885,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4885,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4885:
	.ascii	"exclusive-bound-validation-widened"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4885, 34

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4886,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4886,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4886:
	.ascii	"LinkML 1.11 exposes inclusive minimum_value/maximum_value bounds but no exclusive numeric bounds. An exclusive JSON Schema bound is projected as the corresponding inclusive bound, widening acceptance at the boundary value."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4886, 222

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4887,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4887,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4887:
	.ascii	"A JSON Schema format does not have an exact, uniformly enforced LinkML 1.11 equivalent. The scalar carrier remains constrained and the format name is retained when representable, while validation semantics are widened."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4887, 218

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4888,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4888,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4888:
	.ascii	"keyword-validation-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4888, 26

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4889,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4889,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4889:
	.ascii	"A JSON Schema assertion outside the emitter's closed LinkML 1.11 capability table has no sound projection. The assertion is omitted and recorded at its schema location rather than disappearing silently."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4889, 202

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4890,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4890,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4890:
	.ascii	"JSON Schema multipleOf has no LinkML 1.11 numeric expression. The numeric carrier and other representable bounds remain, while divisibility validation is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4890, 162

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4891,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4891,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4891:
	.ascii	"non-scalar-enum-validation-widened"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4891, 34

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4892,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4892,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4892:
	.ascii	"LinkML 1.11 permissible values are scalar identifiers and cannot encode arbitrary JSON object or array enum members. The representable carrier remains, while non-scalar membership validation is widened."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4892, 202

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4893,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4893,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4893:
	.ascii	"JSON Schema minProperties/maxProperties assertions have no LinkML 1.11 class expression. Named attributes and their requiredness remain, while total property-count validation is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4893, 186

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4894,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4894,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4894:
	.ascii	"slot-identity-rehomed"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4894, 21

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4895,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4895,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4895:
	.ascii	"A source JSON property token without a caller-resolvable RDF identity is assigned to a concrete URI under the caller's configured LinkML default prefix. The source token, generated slot name, and assigned identity remain explicit in the projection report."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4895, 255

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4896,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4896,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4896:
	.ascii	"slot-name-policy-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4896, 24

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4897,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4897,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4897:
	.ascii	"The caller selected LinkML slot-name skipping for a JSON property whose spelling cannot be emitted directly. The single property is omitted and its exact source location remains explicit in the projection diagnostic."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4897, 216

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4898,@object
	.section	.rodata.cst32,"aM",@progbits,32
.Lanon.0baec5b44c5538d1487548c085149cb7.4898:
	.ascii	"string-length-validation-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4898, 32

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4899,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4899,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4899:
	.ascii	"JSON Schema minLength/maxLength assertions have no LinkML 1.11 slot expression. The string carrier and representable pattern remain, while code-point length validation is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4899, 179

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4900,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4900,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4900:
	.ascii	"tuple-array-validation-widened"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4900, 30

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4901,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4901,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4901:
	.ascii	"LinkML 1.11 lists are homogeneous and cannot preserve JSON Schema prefixItems or position-specific item schemas. The list is projected to a sound common item carrier, widening position-specific validation."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4901, 205

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4902,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4902,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4902:
	.ascii	"JSON Schema unevaluatedProperties/unevaluatedItems assertions depend on applicator evaluation state that LinkML 1.11 does not expose. Representable local constraints remain, while the unevaluated assertion is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4902, 217

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4903,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4903,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4903:
	.ascii	"additional-properties-validation-narrowed"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4903, 41

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4904,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4904,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4904:
	.ascii	"GraphQL input objects reject every field not declared by the input type before resolver execution. A JSON Schema object that permits additional properties therefore accepts source keys that the generated GraphQL input type rejects; named fields remain available and the narrowing is recorded on the object schema."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4904, 313

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4905,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4905,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4905:
	.ascii	"array-cardinality-validation-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4905, 36

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4906,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4906,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4906:
	.ascii	"GraphQL list types have no minimum- or maximum-length expression. The generated list retains its item carrier while JSON Schema minItems/maxItems validation is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4906, 168

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4907,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4907,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4907:
	.ascii	"JSON Schema contains/minContains/maxContains quantifies matching array elements. GraphQL list input coercion has no corresponding predicate, so the item carrier remains while contains validation is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4907, 206

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4908,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4908,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4908:
	.ascii	"JSON Schema if/then/else chooses validation constraints from runtime instance content. GraphQL input object definitions cannot express that conditional relationship; independently representable fields remain while the conditional is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4908, 241

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4909,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4909,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4909:
	.ascii	"custom-scalar-validation-delegated"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4909, 34

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4910,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4910,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4910:
	.ascii	"GraphQL SDL declares a custom scalar name but does not define its parseValue, parseLiteral, or serialization behavior. Validation carried by the caller-named fallback scalar is therefore delegated to application code and is not an exact self-contained SDL projection."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4910, 267

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4911,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4911,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4911:
	.ascii	"JSON Schema dependentRequired/dependentSchemas imposes cross-field validation. GraphQL input object definitions express each field independently and cannot enforce those dependencies, so the relationship is omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4911, 215

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4912,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4912,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4912:
	.ascii	"integer-domain-validation-delegated"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4912, 35

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4913,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4913,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4913:
	.ascii	"GraphQL Int accepts only signed 32-bit integers. A JSON Schema integer domain that is not exactly that domain is carried through the caller-named fallback scalar, whose integer acceptance behavior is application-defined."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4913, 220

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4914,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4914,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4914:
	.ascii	"intersection-validation-delegated"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4914, 33

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4915,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4915,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4915:
	.ascii	"General JSON Schema allOf is an intersection of validation sets. GraphQL has no input intersection type, so a non-mergeable intersection is carried through the caller-named fallback scalar and its validation is delegated."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4915, 221

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4916,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4916,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4916:
	.ascii	"keyword-validation-delegated"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4916, 28

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4917,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4917,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4917:
	.ascii	"A JSON Schema assertion outside the emitter's closed GraphQL capability table has no sound SDL expression. Its value is carried through the caller-named fallback scalar and the assertion is recorded rather than silently treated as enforced."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4917, 240

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4918,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4918,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4918:
	.ascii	"negation-validation-delegated"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4918, 29

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4919,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4919,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4919:
	.ascii	"JSON Schema not is a complement of an instance-validation set. GraphQL input types have no complement operator, so the value is carried through the caller-named fallback scalar and negation validation is delegated."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4919, 214

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4920,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4920,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4920:
	.ascii	"nullable-presence-validation-widened"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4920, 36

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4921,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4921,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4921:
	.ascii	"GraphQL uses one nullable field form for both omission and an explicit null. JSON Schema can distinguish required nullable properties from optional non-null properties; either source distinction must be widened when represented by a nullable GraphQL input field."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4921, 262

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4922,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4922,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4922:
	.ascii	"numeric-validation-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4922, 26

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4923,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4923,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4923:
	.ascii	"GraphQL Int and Float types do not express JSON Schema bounds, exclusive bounds, or multipleOf. The built-in numeric carrier remains while those runtime predicates are omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4923, 176

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4924,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4924,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4924:
	.ascii	"one-of-validation-delegated"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4924, 27

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4925,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4925,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4925:
	.ascii	"JSON Schema oneOf requires exactly one branch to validate. GraphQL has no input union with exactly-one validation semantics, so a non-finite oneOf is carried through the caller-named fallback scalar and exclusivity is delegated."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4925, 228

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4926,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4926,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4926:
	.ascii	"pattern-properties-validation-changed"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4926, 37

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4927,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4927,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4927:
	.ascii	"JSON Schema patternProperties can admit dynamic regex-selected keys and can add conjunctive validation to declared keys. GraphQL input objects instead expose a fixed field set with one type per field, so dynamic keys are narrowed while overlapping declared-field validation may be widened."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4927, 289

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4928,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4928,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4928:
	.ascii	"JSON Schema minProperties/maxProperties counts runtime object keys. GraphQL input object definitions express field requiredness but cannot bound the total supplied-field count."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4928, 176

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4929,@object
	.section	.rodata.cst32,"aM",@progbits,32
.Lanon.0baec5b44c5538d1487548c085149cb7.4929:
	.ascii	"property-name-validation-changed"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4929, 32

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4930,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4930,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4930:
	.ascii	"JSON Schema propertyNames validates every runtime key, including declared properties. GraphQL input objects expose only a fixed declared field set: unknown names are narrowed, while a source property-name rule that rejects a generated declared field is not enforced and may widen acceptance."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4930, 291

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4931,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4931,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4931:
	.ascii	"recursive-input-nullability-relaxed"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4931, 35

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4932,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4932,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4932:
	.ascii	"GraphQL forbids an unbroken cycle of singular non-null input-object fields because no finite value can satisfy it. The emitter makes one deterministic cycle edge nullable and records that required/non-null source constraint at the field location."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4932, 246

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4933,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4933,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4933:
	.ascii	"singleton-list-coercion-widened"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4933, 31

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4934,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4934,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4934:
	.ascii	"GraphQL variable coercion accepts a non-list value for list input and wraps it as a single-element list. JSON Schema array validation rejects that same non-array value, so every generated list input has this explicit coercion widening."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4934, 235

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4935,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4935,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4935:
	.ascii	"string-validation-dropped"
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4935, 25

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4936,@object
	.section	.rodata..Lanon.0baec5b44c5538d1487548c085149cb7.4936,"a",@progbits
.Lanon.0baec5b44c5538d1487548c085149cb7.4936:
	.ascii	"GraphQL String has no length, regular-expression, format, or content assertion. The string carrier remains while JSON Schema string predicates are omitted."
	.size	.Lanon.0baec5b44c5538d1487548c085149cb7.4936, 155

	.type	.Lanon.0baec5b44c5538d1487548c085149cb7.4937,@object
	.section	.rodata.cst32,"aM",@progbits,32
.Lanon.0baec5b44c5538d1487548c085149cb7.4937:
